style.css:
@-moz-document domain("pinterest.com") {
/* Fondo principal estilo Cutecore con rayas o color rosa suave */
    body, #__PWS_ROOT__, .appContent {
        background-color: #ffb7d5 !important;
        background-image: linear-gradient(90deg, rgba(255,255,255,.15) 50%, transparent 50%) !important;
        background-size: 40px 40px !important;
    }

    /* Modifica la barra de búsqueda y navegación superior */
    .HeaderContent, [data-test-id="header"] {
        background-color: #ffffff !important;
        border-bottom: 4px dashed #ff69b4 !important;
    }

    /* Redondeado extra para las tarjetas de Pines y bordes suaves */
    [data-test-id="pin"], .Grid__Item, img {
        border-radius: 24px !important;
        border: 2px solid #ffdeeb !important;
        box-shadow: 0px 4px 10px rgba(255, 105, 180, 0.2) !important;
    }

    /* Botón de Guardar en color rosa vibrante */
    [data-test-id="PinCardShareButton"], [data-test-id="board-section-save-button"], .red.rounded {
        background-color: #ff65a3 !important;
        color: white !important;
    }
}
